          modelChange == other.modelChange;
}

@freezed
sealed class SettingsPick with _$SettingsPick {
  const SettingsPick._();

  const factory SettingsPick.effort({required String level}) =
      SettingsPick_Effort;
  const factory SettingsPick.auto() = SettingsPick_Auto;
  const factory SettingsPick.planMode({required bool enabled}) =
      SettingsPick_PlanMode;

  /// The catalog row `id`, run on `execution_harness` (else the chat's
  /// locked harness).
  const factory SettingsPick.model({
    required String id,
    String? executionHarness,
  }) = SettingsPick_Model;
  const factory SettingsPick.fast({required bool fast}) = SettingsPick_Fast;
}

/// What a composer source captured when the host built it: a read fails
/// when the shown chat no longer matches.
class SourceScopeView {
  final ChatRefView chat;
  final int generation;

  /// The tab's `model` and `executionHarness`, in bridge-form JSON.
  final String modelJson;
  final String harnessJson;

  const SourceScopeView({
    required this.chat,
    required this.generation,
    required this.modelJson,
    required this.harnessJson,
  });

  @override
  int get hashCode =>
      chat.hashCode ^
      generation.hashCode ^
      modelJson.hashCode ^
      harnessJson.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SourceScopeView &&
          runtimeType == other.runtimeType &&
          chat == other.chat &&
          generation == other.generation &&
          modelJson == other.modelJson &&
          harnessJson == other.harnessJson;
}

/// `CanopyEffortSpeed`.
enum SpeedView { regular, fast, ultraFast }
